     4	// Incidents, newest first. Open ones by default; ?state=resolved shows the
     5	// resolved ones instead.
     6	export function renderIncidents(snapshot, query) {
     7	  const state = query.state === 'resolved' ? 'resolved' : 'open';
     8	  const incidents = snapshot.incidents
     9	    .filter((i) => (state === 'open' ? i.resolvedAt === null : i.resolvedAt !== null))
    10	    .sort((a, b) => b.openedAt.localeCompare(a.openedAt));
    11	
    12	  const tab = (value, label) => {
    13	    const current = value === state ? ' aria-current="page"' : '';
    14	    return `<a href="/incidents?state=${value}"${current}>${label}</a>`;
    15	  };
    16	
    17	  const items = incidents
    18	    .map((i) => {
    19	      const runbook = button({
    20	        label: 'Runbook',
    21	        href: `/runbooks#${encodeURIComponent(i.runbook)}`,
    22	        variant: 'link',
    23	        size: 'sm',
    24	      });
    25	      return `<li class="incident">
    26	  <span class="pill ${severityClass(i.severity)}">${escapeHtml(i.severity)}</span>
    27	  <strong>${escapeHtml(i.title)}</strong>
    28	  <span class="muted">${escapeHtml(i.service)}, opened ${escapeHtml(i.openedAt)}</span>
    29	  ${runbook}
    30	</li>`;
    31	    })
    32	    .join('\n');
    33	
    34	  const list =
    35	    incidents.length === 0
    36	      ? `<p class="muted">No ${state} incidents.</p>`
    37	      : `<ul class="incidents">
    38	${items}
    39	</ul>`;
    40	
    41	  return `<h1>Incidents</h1>
    42	<nav class="subnav">${tab('open', 'Open')}${tab('resolved', 'Resolved')}</nav>
    43	${list}`;
    44	}
    45	
    46	function severityClass(severity) {
    47	  if (severity === 'sev1') return 'pill-red';
    48	  if (severity === 'sev2') return 'pill-amber';
    49	  return 'pill-grey';
    50	}
