100	     5	import { readSnapshot } from './data.js';
101	     6	import { escapeHtml } from './html.js';
102	     7	import { layout } from './layout.js';
103	     8	import { renderIncidents } from './pages/incidents.js';
104	     9	import { renderOncall } from './pages/oncall.js';
105	    10	import { renderOverview } from './pages/overview.js';
106	    11	import { renderRunbooks } from './pages/runbooks.js';
107	    12	import { renderServices } from './pages/services.js';
108	    13	
109	    14	const PUBLIC_DIR = fileURLToPath(new URL('../public/', import.meta.url));
110	    15	const TYPES = { '.css': 'text/css', '.js': 'text/javascript' };
111	    16	
112	    17	const ROUTES = {
113	    18	  '/': { title: 'Overview', snapshot: 'services', render: renderOverview },
114	    19	  '/services': { title: 'Services', snapshot: 'services', render: renderServices },
115	    20	  '/incidents': { title: 'Incidents', snapshot: 'incidents', render: renderIncidents },
116	    21	  '/oncall': { title: 'On-call', snapshot: 'oncall', render: renderOncall },
117	    22	  '/runbooks': { title: 'Runbooks', snapshot: 'runbooks', render: renderRunbooks },
118	    23	};
119	    24	
120	    25	// Resolves one request to a response. Kept apart from the http server so
121	    26	// tests can call it directly.
122	    27	export async function handle(url, { dataDir } = {}) {
123	    28	  const { pathname, searchParams } = new URL(url, 'http://harbor.local');
124	    29	  if (pathname.startsWith('/public/')) return serveStatic(pathname.slice('/public/'.length));
125	    30	  const route = ROUTES[pathname];
126	    31	  if (!route) return page(404, 'Not found', '<h1>Not found</h1>', pathname);
127	    32	  let snapshot;
128	    33	  try {
129	    34	    snapshot = await readSnapshot(route.snapshot, dataDir);
